// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';


export type AntiqueYoYoProps = Record<string, any>;

const AntiqueYoYo: React.FC<AntiqueYoYoProps> = ({
  backgroundColor = "#1a1612",
  transparentBackground = false,
  durationInSeconds = 8,
  woodBaseColor = "#4A2E15",
  woodHighlightColor = "#7A4C24",
  metalPinColor = "#B89947",
  stringColor = "#E8DCC4",
  bounceSpeed = 1.2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing
  const yoyoSize = Math.min(width, height) * 0.35;
  const centerX = width * 0.5;

  // Animation Cycle Math
  const cycleLength = fps * (2 / bounceSpeed);
  const localFrame = frame % cycleLength;

  // Keyframes for the bounce
  const topY = height * 0.15;
  const bottomY = height * 0.75;
  
  // Timings within the cycle
  const dropEnd = cycleLength * 0.45;
  const sleepEnd = cycleLength * 0.55;

  // Calculate Vertical Position
  let yPos = topY;
  if (localFrame < dropEnd) {
    // Dropping (Accelerating via ease-in)
    yPos = interpolate(localFrame, [0, dropEnd], [topY, bottomY], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.in(Easing.poly(2)),
    });
  } else if (localFrame < sleepEnd) {
    // Sleeping at the bottom
    yPos = bottomY;
  } else {
    // Returning (Decelerating via ease-out)
    yPos = interpolate(
      localFrame,
      [sleepEnd, cycleLength],
      [bottomY, topY],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
        easing: Easing.out(Easing.poly(2)),
      }
    );
  }

  // Calculate continuous spin
  const spinAngle = (frame * 18) % 360;

  // Dynamic Shadow underneath the yo-yo
  const shadowOpacity = interpolate(yPos, [topY, bottomY], [0, 0.6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const shadowScale = interpolate(yPos, [topY, bottomY], [0.3, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background Vignette for mood */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at center, transparent 30%, rgba(0,0,0,0.6) 100%)`,
        }}
      />

      {/* Dynamic Floor Shadow */}
      <div
        style={{
          position: "absolute",
          left: centerX - yoyoSize * 0.4,
          top: bottomY + yoyoSize * 0.45,
          width: yoyoSize * 0.8,
          height: yoyoSize * 0.15,
          backgroundColor: "black",
          borderRadius: "50%",
          filter: "blur(12px)",
          opacity: shadowOpacity,
          transform: `scale(${shadowScale})`,
          transition: "none",
        }}
      />

      {/* The String */}
      <div
        style={{
          position: "absolute",
          left: centerX - 2, // 4px wide string, offset by half
          top: -100, // Extend well beyond top of canvas
          width: 4,
          height: yPos + 100, // Reach exactly to the center of the yo-yo
          backgroundColor: stringColor,
          boxShadow: "0px 0px 4px rgba(0,0,0,0.5)",
          transition: "none",
        }}
      />

      {/* The Yo-Yo Container */}
      <div
        style={{
          position: "absolute",
          left: centerX - yoyoSize / 2,
          top: yPos - yoyoSize / 2,
          width: yoyoSize,
          height: yoyoSize,
          transition: "none",
        }}
      >
        <svg
          width={yoyoSize}
          height={yoyoSize}
          viewBox="0 0 100 100"
          style={{ overflow: "visible" }}
        >
          <defs>
            {/* Antique Wood Shading Gradient */}
            <radialGradient
              id="woodGradient"
              cx="45%"
              cy="45%"
              r="55%"
              fx="35%"
              fy="35%"
            >
              <stop offset="0%" stopColor={woodHighlightColor} />
              <stop offset="60%" stopColor={woodBaseColor} />
              <stop offset="100%" stopColor="#25170A" />
            </radialGradient>

            {/* Deep Recess Gradient */}
            <radialGradient id="recessGradient" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="#25170A" />
              <stop offset="80%" stopColor={woodBaseColor} />
              <stop offset="100%" stopColor="#150C05" />
            </radialGradient>

            {/* Brass Pin Gradient */}
            <radialGradient id="brassGradient" cx="30%" cy="30%" r="70%">
              <stop offset="0%" stopColor="#FFE082" />
              <stop offset="40%" stopColor={metalPinColor} />
              <stop offset="100%" stopColor="#5C4D24" />
            </radialGradient>

            {/* Drop Shadow for the main body */}
            <filter id="yoyoShadow" x="-10%" y="-10%" width="130%" height="130%">
              <feDropShadow dx="0" dy="8" stdDeviation="6" floodOpacity="0.4" />
            </filter>
          </defs>

          {/* Main Outer Rim */}
          <circle
            cx="50"
            cy="50"
            r="48"
            fill="url(#woodGradient)"
            filter="url(#yoyoShadow)"
          />

          {/* Inner Step (Lathe turned detail) */}
          <circle
            cx="50"
            cy="50"
            r="38"
            fill="none"
            stroke="#25170A"
            strokeWidth="1.5"
            opacity="0.6"
          />
          <circle
            cx="50"
            cy="50"
            r="36"
            fill="none"
            stroke={woodHighlightColor}
            strokeWidth="0.5"
            opacity="0.4"
          />

          {/* Deep Recess Area */}
          <circle cx="50" cy="50" r="28" fill="url(#recessGradient)" />

          {/* Spinning Details Group */}
          <g
            style={{
              transform: `rotate(${spinAngle}deg)`,
              transformOrigin: "50px 50px",
              transition: "none",
            }}
          >
            {/* Dashed engraved ring to emphasize spinning motion */}
            <circle
              cx="50"
              cy="50"
              r="22"
              fill="none"
              stroke="#150C05"
              strokeWidth="2"
              strokeDasharray="4 6"
              opacity="0.7"
            />
            {/* Subtle wood grain/lathe lines */}
            <circle
              cx="50"
              cy="50"
              r="16"
              fill="none"
              stroke={woodHighlightColor}
              strokeWidth="1"
              strokeDasharray="12 4 2 4"
              opacity="0.3"
            />
            <circle
              cx="50"
              cy="50"
              r="10"
              fill="none"
              stroke="#150C05"
              strokeWidth="0.5"
              opacity="0.5"
            />
          </g>

          {/* Center Brass Axle Pin */}
          <circle
            cx="50"
            cy="50"
            r="6"
            fill="url(#brassGradient)"
            stroke="#3E3418"
            strokeWidth="0.5"
          />
          
          {/* Highlight on Pin for extra dimension */}
          <circle
            cx="48"
            cy="48"
            r="1.5"
            fill="#FFFFFF"
            opacity="0.4"
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default AntiqueYoYo;